import {useEffect} from 'react';
import vendor from './framo/vendor.txt';
import main from './framo/main.txt';
import swiper from './framo/vendor-swiper.txt';
import lightbox from './framo/vendor-glightbox.txt';
import gsap from './framo/vendor-gsap.txt';
import shop from './framo/shop.txt';
export function useTemplateRuntime(page){
 useEffect(()=>{
  const inject=code=>{const script=document.createElement('script');script.textContent=code;document.body.append(script);script.remove();};
  if(!window.FramoVendor){
   [vendor,swiper,lightbox,gsap,shop].forEach(inject);
   window.FramoVendor.load=(name)=>window.FramoVendor.ready?.includes(name)?Promise.resolve(window.FramoVendor):Promise.reject(new Error('Optional feature '+name+' is not connected in this starter.'));
  }
  inject(main);
  document.querySelectorAll('.nav-link[href]').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#page='+page));
  window.scrollTo(0,0);
  const anchor=new URLSearchParams(location.hash.slice(1)).get('anchor');
  if(anchor)document.getElementById(anchor)?.scrollIntoView();
  return ()=>{const root=document.getElementById('template-page');if(root)window.FramoVendor?.Alpine?.destroyTree(root);};
 },[page]);
}
